import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { filterSecondarySchools } from "../src/lib/secondary-school-filter.ts";
import { normalizePlanningDistrict } from "../src/lib/planning-district.ts";
import { getSecondaryTeachingMedium } from "./secondary-teaching-medium.mjs";

const criteria = (overrides = {}) => ({
  route: "dse",
  queryTerms: [],
  district: "all",
  studentGender: "all",
  schoolType: "all",
  language: "all",
  ...overrides,
});
const record = (id, facts = {}, overrides = {}) => ({
  id,
  routes: ["dse"],
  searchVariants: [id],
  facts: { district: "沙田区", gender: "Co-ed", schoolType: "public-funded", teachingMedium: { chinese: true, english: false }, ...facts },
  ...overrides,
});

const genderRecords = [record("boys", { gender: "Boys" }), record("girls", { gender: "Girls" }), record("coed", { gender: "Co-ed" })];
assert.deepEqual(filterSecondarySchools(genderRecords, criteria({ studentGender: "boy" })).matches.map(({ id }) => id), ["boys", "coed"]);
assert.deepEqual(filterSecondarySchools(genderRecords, criteria({ studentGender: "girl" })).matches.map(({ id }) => id), ["girls", "coed"]);

const candidates = [
  record("sha-tin-boy-dse", { gender: "Boys" }),
  record("sha-tin-coed-ib", { gender: "Co-ed" }, { routes: ["ib"] }),
  record("kowloon-boy-dse", { district: "九龙城区", gender: "Boys" }),
];
assert.equal(normalizePlanningDistrict("西贡区"), "西貢區");
assert.deepEqual(
  filterSecondarySchools([record("traditional-district", { district: "西貢區" })], criteria({ district: "西贡区" })).matches.map(({ id }) => id),
  ["traditional-district"],
  "secondary filters must accept the same district in either Chinese form",
);
assert.deepEqual(
  filterSecondarySchools(candidates, criteria({ district: "沙田区", studentGender: "boy" })).matches.map(({ id }) => id),
  ["sha-tin-boy-dse"],
  "district, gender, and selected route should all be applied together",
);
assert.deepEqual(
  filterSecondarySchools(candidates, criteria({ route: "ib", district: "九龙城区" })).matches,
  [],
  "route and district mismatches must not fall back to unrelated schools",
);
assert.deepEqual(
  filterSecondarySchools(candidates, criteria({ queryTerms: ["sha-tin"] })).matches.map(({ id }) => id),
  ["sha-tin-boy-dse"],
  "search terms should be applied together with selected route and school filters",
);

const missing = record("missing", { district: null, gender: null, schoolType: null, teachingMedium: null });
const excluded = record("known-mismatch", { district: "九龙城区", gender: null });
const unknownResult = filterSecondarySchools([missing, excluded], criteria({ district: "沙田区", studentGender: "girl" }));
assert.deepEqual(unknownResult.matches, []);
assert.equal(unknownResult.unclassifiedCount, 1, "only candidates that could otherwise match are counted as unclassified");
const zeroResult = filterSecondarySchools([record("wrong-route", {}, { routes: ["ib"] })], criteria());
assert.deepEqual(zeroResult.matches, [], "verified zero matches must remain empty");
assert.equal(zeroResult.unclassifiedCount, 0);

const languages = [
  record("chinese-only", { teachingMedium: { chinese: true, english: false } }),
  record("bilingual", { teachingMedium: { chinese: true, english: true } }),
  record("english-only", { teachingMedium: { chinese: false, english: true } }),
  record("unknown-language", { teachingMedium: null }),
];
assert.deepEqual(filterSecondarySchools(languages, criteria({ language: "bilingual" })).matches.map(({ id }) => id), ["bilingual"]);
assert.deepEqual(filterSecondarySchools(languages, criteria({ language: "english" })).matches.map(({ id }) => id), ["bilingual", "english-only"]);
assert.equal(filterSecondarySchools(languages, criteria({ language: "english" })).unclassifiedCount, 1);

const directory = JSON.parse(await readFile(new URL("../src/content/secondary-school-directory-2025-2026.json", import.meta.url), "utf8"));
const catalog = JSON.parse(await readFile(new URL("../src/content/secondary-school-planning-candidates.json", import.meta.url), "utf8"));
assert.equal(catalog.metadata.sourceEdition, directory.metadata.sourceEdition);
assert.equal(catalog.metadata.verifiedOn, directory.metadata.latestEditionCheckedOn);
assert.match(catalog.metadata.sourceUrl, /^https:\/\//);
const cwc = directory.schools.find(({ id }) => id === "po-leung-kuk-c-w-chu-college-7ad453");
const wyk = directory.schools.find(({ id }) => id === "wah-yan-college-kowloon-9461a9");
const cwcMedium = getSecondaryTeachingMedium(cwc.subjectOfferingsByMedium["2025_2026"]);
const wykMedium = getSecondaryTeachingMedium(wyk.subjectOfferingsByMedium["2025_2026"]);
assert.deepEqual(cwcMedium, { chinese: true, english: false }, "English Language alone is not evidence of English-medium non-language subjects");
assert.deepEqual(wykMedium, { chinese: true, english: true }, "non-language subject entries support both languages for Wah Yan Kowloon");
assert.equal(getSecondaryTeachingMedium({ junior: { chinese: "Chinese Language", english: "English Language" } }), null);
assert.equal(getSecondaryTeachingMedium({ junior: { english: "S.1 to S.3: English Language" } }), null);

const catalogRecords = catalog.schools.map((school) => ({
  school,
  routes: school.routes,
  searchVariants: Object.values(school.names ?? {}).filter(Boolean).map((name) => name.toLocaleLowerCase()),
  facts: {
    district: school.district,
    districtScopes: school.districtScopes,
    gender: school.gender,
    schoolType: school.schoolType,
    teachingMedium: school.teachingMedium,
  },
}));
const actualFiltered = filterSecondarySchools(catalogRecords, criteria({
  district: "沙田区",
  studentGender: "boy",
  schoolType: "public-funded",
}));
assert.ok(actualFiltered.matches.length > 0, "real candidate catalog should produce results for a viable filter set");
assert.ok(actualFiltered.matches.every(({ facts }) => facts.district === "沙田区" && ["Boys", "Co-ed"].includes(facts.gender) && facts.schoolType === "public-funded"));
const cwcCandidate = catalogRecords.find(({ school }) => school.profileId === "po-leung-kuk-c-w-chu-college-7ad453");
assert.ok(cwcCandidate);
assert.ok(filterSecondarySchools([cwcCandidate], criteria({ language: "chinese" })).matches.length === 1);
assert.equal(filterSecondarySchools([cwcCandidate], criteria({ language: "english" })).matches.length, 0);
assert.equal(filterSecondarySchools([cwcCandidate], criteria({ language: "bilingual" })).matches.length, 0);
const wykCandidate = catalogRecords.find(({ school }) => school.profileId === "wah-yan-kowloon");
assert.ok(wykCandidate);
assert.equal(filterSecondarySchools([wykCandidate], criteria({ studentGender: "girl" })).matches.length, 0);
assert.equal(filterSecondarySchools([wykCandidate], criteria({ studentGender: "boy" })).matches.length, 1);
const isfCandidate = catalogRecords.find(({ school }) => school.profileId === "isf-academy");
assert.ok(isfCandidate, "the curated ISF all-through school profile should create a secondary candidate");
assert.deepEqual(isfCandidate.routes, ["ib"], "ISF should expose only the verified IB route");
assert.equal(filterSecondarySchools([isfCandidate], criteria({ route: "dse" })).matches.length, 0, "ISF must not receive an unsupported DSE tag");
assert.equal(filterSecondarySchools([isfCandidate], criteria({ route: "a-level" })).matches.length, 0, "ISF must not receive an unsupported A-Level tag");
assert.equal(isfCandidate.school.district, "南区", "ISF candidate should use the verified school district");
assert.equal(isfCandidate.school.gender, "Co-ed", "ISF candidate should use the verified co-educational status");
assert.equal(filterSecondarySchools([isfCandidate], criteria({ route: "ib", district: "南区", studentGender: "girl", schoolType: "international" })).matches.length, 1, "ISF should match its verified route, district, gender, and international type filters");
assert.equal(filterSecondarySchools([isfCandidate], criteria({ route: "ib", district: "南区", studentGender: "boy", schoolType: "international" })).matches.length, 1, "ISF co-ed status should admit boys as well as girls");
assert.ok(isfCandidate.school.routeEvidence.find(({ route }) => route === "ib")?.sources.some(({ sourceUrl }) => sourceUrl === "https://www.ibo.org/en/school/002876/"));
const isfProfile = JSON.parse(await readFile(new URL("../src/content/secondary-school-planning.json", import.meta.url), "utf8")).schools.find(({ id }) => id === "isf-academy");
const isf2026Results = isfProfile?.snapshot.find(({ field }) => field === "2026届IBDP成绩及大学录取（校方公布）");
assert.ok(isf2026Results);
assert.match(isf2026Results.value, /2026届毕业班共101人/u);
assert.match(isf2026Results.value, /49人（49%）取得40分或以上/u);
assert.match(isf2026Results.value, /77%获双语文凭/u);
assert.match(isf2026Results.value, /140所高等院校的735份录取通知/u);
assert.match(isf2026Results.value, /未列总体文凭通过率/u);
assert.match(isf2026Results.value, /不等于独立学生数、最终入读人数/u);
assert.equal(isf2026Results.sourceUrl, "https://academy.isf.edu.hk/index.php/achievements-and-news/class-of-2026-ibdp-results/");
assert.equal(isfProfile.verifiedOn, "2026-10-12", "ISF profile review should be dated");
const isfPrimary = isfProfile.snapshot.find(({ field }) => field === "小学课程与 IB 准备");
assert.ok(isfPrimary);
assert.match(isfPrimary.value, /双语沉浸式课程/u);
assert.match(isfPrimary.value, /没有把该小学课程称为 IB PYP/u, "ISF primary must not be labeled as PYP without authorization");
const isfProgrammes = isfProfile.snapshot.find(({ field }) => field === "中学 IB 课程路线");
assert.ok(isfProgrammes);
assert.match(isfProgrammes.value, /Middle Years Programme（MYP）及 Diploma Programme（DP）/u);
assert.match(isfProgrammes.value, /不代表每名学生必然修读完整 IBDP/u);
const isfProgression = isfProfile.snapshot.find(({ field }) => field === "校内升学与 DP 选择边界");
assert.ok(isfProgression);
assert.match(isfProgression.value, /不能从同校课程设置推定无条件升中或保证进入 IBDP/u);
assert.ok(isfProfile.pending.some((item) => /内部资格、评核和通知安排/u.test(item)));
assert.ok(isfProfile.pending.some((item) => /按下一学年更新学费/u.test(item)));
const isfTimeline = isfProfile.snapshot.find(({ field }) => field === "2027/28各年级常规申请截止日期（截至2026-10-12）");
assert.ok(isfTimeline);
assert.equal(isfTimeline.sourceUrl, "https://academy.isf.edu.hk/index.php/welcome-from-dean-of-admissions/admissions-policy/admissions-timeline/");
assert.match(isfTimeline.value, /申请于2026年8月1日开始/u);
assert.match(isfTimeline.value, /Foundation Year.*2026年8月31日.*2026年9月15日/u);
assert.match(isfTimeline.value, /Grade 1为2026年11月5日/u);
assert.match(isfTimeline.value, /Grade 2–5为2027年1月25日/u);
assert.match(isfTimeline.value, /Grade 6–11为2026年11月22日/u);
assert.match(isfTimeline.value, /滚动招生/u);
assert.match(isfTimeline.value, /不保证某年级会开/u);
const isfEligibility = isfProfile.snapshot.find(({ field }) => field === "2027/28入学资格与语言要求");
assert.ok(isfEligibility);
assert.equal(isfEligibility.sourceUrl, "https://academy.isf.edu.hk/index.php/welcome-from-dean-of-admissions/admissions-policy/");
assert.match(isfEligibility.value, /至少一名家长／法定监护人居住香港/u);
assert.match(isfEligibility.value, /没有单独的语言门槛/u);
assert.match(isfEligibility.value, /不保证获录取/u);
const isfAssessment = isfProfile.snapshot.find(({ field }) => field.startsWith("入学评估流程及防中介提示"));
assert.ok(isfAssessment);
assert.equal(isfAssessment.sourceUrl, "https://academy.isf.edu.hk/index.php/welcome-from-dean-of-admissions/admissions-policy/admissions-assessment-process/");
assert.match(isfAssessment.value, /分阶段评估/u);
assert.match(isfAssessment.value, /未能出席可导致申请终止且申请费不退/u);
assert.match(isfAssessment.value, /没有委任或授权任何代理或第三方/u);
const isfFees = isfProfile.snapshot.find(({ field }) => field === "2026/27年度学费与额外支出");
assert.ok(isfFees);
assert.equal(isfFees.sourceUrl, "https://academy.isf.edu.hk/index.php/welcome-from-dean-of-admissions/fees-tuition/");
assert.match(isfFees.value, /HK\$251,130/u);
assert.match(isfFees.value, /HK\$291,770/u);
assert.match(isfFees.value, /HK\$317,190/u);
assert.match(isfFees.value, /分10期/u);
assert.match(isfFees.value, /不能把2026\/27数字当成2027\/28报价/u);
const isfAid = isfProfile.snapshot.find(({ field }) => field === "经济援助范围与申请边界");
assert.ok(isfAid);
assert.equal(isfAid.sourceUrl, "https://academy.isf.edu.hk/index.php/welcome-from-dean-of-admissions/fees-tuition/financial-aid/");
assert.match(isfAid.value, /need-blind/u);
assert.match(isfAid.value, /20%–100%学费/u);
assert.match(isfAid.value, /酌情决定/u);
assert.match(isfAid.value, /2027\/28时程与材料须另行核实/u);
const isfHowToApply = isfProfile.snapshot.find(({ field }) => field === "申请平台及所需材料");
assert.ok(isfHowToApply);
assert.equal(isfHowToApply.sourceUrl, "https://academy.isf.edu.hk/index.php/welcome-from-dean-of-admissions/admissions-policy/how-to-apply/");
assert.match(isfHowToApply.value, /Friends of ISF线上提交/u);
assert.match(isfHowToApply.value, /Grade 2–11还需/u);
assert.match(isfHowToApply.value, /具体文件以目标年级当届系统清单为准/u);
const spccCandidate = catalogRecords.find(({ school }) => school.profileId === "spcc");
assert.ok(spccCandidate, "St. Paul's Co-educational College should remain in the curated candidate set");
assert.deepEqual(spccCandidate.routes, ["dse", "ib"]);
assert.equal(spccCandidate.school.district, "中西区");
assert.equal(spccCandidate.school.gender, "Co-ed");
assert.equal(spccCandidate.school.schoolType, "dss");
assert.equal(filterSecondarySchools([spccCandidate], criteria({ route: "dse", district: "中西区", studentGender: "boy" })).matches.length, 1);
assert.equal(filterSecondarySchools([spccCandidate], criteria({ route: "ib", district: "中西区", studentGender: "girl" })).matches.length, 1);
assert.equal(filterSecondarySchools([spccCandidate], criteria({ route: "a-level" })).matches.length, 0);
const spccProfile = JSON.parse(await readFile(new URL("../src/content/secondary-school-planning.json", import.meta.url), "utf8")).schools.find(({ id }) => id === "spcc");
assert.equal(spccProfile.verifiedOn, "2026-10-12");
const spccAdmissionStatus = spccProfile.snapshot.find(({ field }) => field === "2027/28中一招生公告状态（截至2026-10-12）");
assert.ok(spccAdmissionStatus);
assert.match(spccAdmissionStatus.value, /仍展示2026\/27申请轮次并标示已截止/u);
assert.match(spccAdmissionStatus.value, /约100个名额及2025-10-27至2025-11-14申请日期均属上一轮/u);
assert.match(spccAdmissionStatus.value, /尚未提供2027\/28申请日期/u);
assert.match(spccAdmissionStatus.value, /不得把上一轮约数和日期沿用/u);
assert.equal(spccAdmissionStatus.sourceUrl, "https://www.spcc.edu.hk/admissions/local-admissions/secondary/f1");
assert.ok(spccProfile.pending.some((item) => /截至2026-10-12已核对的校方中一页面仍只显示/u.test(item)));

const cisCandidate = catalogRecords.find(({ school }) => school.profileId === "cis");
assert.ok(cisCandidate, "CIS should remain in the school-profile candidate set");
assert.deepEqual(cisCandidate.routes, ["ib"], "CIS's documented MYP/DP profile should remain IB-only");
assert.equal(cisCandidate.school.district, "东区");
assert.equal(cisCandidate.school.gender, "Co-ed");
assert.equal(cisCandidate.school.schoolType, "international");
assert.deepEqual(cisCandidate.school.teachingMedium, { chinese: false, english: true }, "CIS secondary English-medium teaching must not be mistaken for bilingual non-language instruction");
assert.equal(filterSecondarySchools([cisCandidate], criteria({ route: "ib", district: "东区", studentGender: "girl", schoolType: "international", language: "english" })).matches.length, 1);
assert.equal(filterSecondarySchools([cisCandidate], criteria({ route: "ib", language: "chinese" })).matches.length, 0);
assert.equal(filterSecondarySchools([cisCandidate], criteria({ route: "dse" })).matches.length, 0);
assert.equal(filterSecondarySchools([cisCandidate], criteria({ route: "a-level" })).matches.length, 0);
assert.ok(cisCandidate.school.routeEvidence.find(({ route }) => route === "ib")?.sources.some(({ sourceUrl }) => sourceUrl === "https://www.cis.edu.hk/academics/secondary/overview"));
const naisCandidate = catalogRecords.find(({ school }) => school.profileId === "nord-anglia-international-school-hong-kong");
assert.ok(naisCandidate, "NAIS should be added to the curated secondary candidate set");
assert.deepEqual(naisCandidate.routes.slice().sort(), ["a-level", "ib"], "NAIS should expose only its verified IBDP and A-Level routes");
assert.equal(naisCandidate.school.district, null, "NAIS should not collapse two campuses into one district");
assert.deepEqual(naisCandidate.school.districtScopes, [
  { district: "观塘区", ageRange: "10–16岁", routes: [] },
  { district: "九龙城区", ageRange: "16–18岁", routes: ["ib", "a-level"] },
], "NAIS should retain the EDB-listed age ranges and route-specific Sixth Form campus");
assert.equal(naisCandidate.school.gender, "Co-ed", "NAIS should use the EDB-listed co-educational status");
assert.equal(naisCandidate.school.schoolType, "international");
assert.equal(naisCandidate.school.teachingMedium, null, "unknown secondary teaching-medium details must remain unclassified rather than inferred from the primary label");
assert.equal(filterSecondarySchools([naisCandidate], criteria({ route: "ib", district: "观塘区", studentGender: "boy", schoolType: "international" })).matches.length, 0, "NAIS IB must not appear under its Kwun Tong campus where the EDB entry does not list the Sixth Form route");
assert.equal(filterSecondarySchools([naisCandidate], criteria({ route: "ib", district: "九龙城区", studentGender: "boy", schoolType: "international" })).matches.length, 1, "NAIS IB should match under its EDB-listed Hung Hom campus district");
assert.equal(filterSecondarySchools([naisCandidate], criteria({ route: "a-level", district: "九龙城区", studentGender: "girl", schoolType: "international" })).matches.length, 1, "NAIS A-Level should match the same verified Sixth Form campus for girls");
assert.equal(filterSecondarySchools([naisCandidate], criteria({ route: "all", district: "观塘区" })).matches.length, 1, "NAIS should remain discoverable by its Kwun Tong secondary campus when no route-specific filter is chosen");
assert.equal(filterSecondarySchools([naisCandidate], criteria({ route: "ib", district: "黄大仙区" })).matches.length, 0, "NAIS should not match unrelated districts");
assert.equal(filterSecondarySchools([naisCandidate], criteria({ route: "ib", district: "九龙城区", language: "english" })).unclassifiedCount, 1, "EDB primary-medium label must not be used to classify NAIS secondary teaching medium");
assert.equal(filterSecondarySchools([naisCandidate], criteria({ route: "a-level", schoolType: "international" })).matches.length, 1, "NAIS should match its verified A-Level route");
assert.equal(filterSecondarySchools([naisCandidate], criteria({ route: "dse" })).matches.length, 0, "NAIS should not be assigned a DSE route without evidence");
assert.ok(naisCandidate.school.routeEvidence.find(({ route }) => route === "ib")?.sources.some(({ sourceUrl }) => sourceUrl.includes("ib-diploma")));
assert.ok(naisCandidate.school.routeEvidence.find(({ route }) => route === "a-level")?.sources.some(({ sourceUrl }) => sourceUrl.includes("a-level")));
const naisProfile = JSON.parse(await readFile(new URL("../src/content/secondary-school-planning.json", import.meta.url), "utf8")).schools.find(({ id }) => id === "nord-anglia-international-school-hong-kong");
assert.ok(naisProfile.snapshot.some(({ sourceUrl }) => sourceUrl === "https://internationalschools.edb.gov.hk/en/schools/31.html"));
assert.ok(naisProfile.snapshot.some(({ sourceUrl }) => sourceUrl === "https://internationalschools.edb.gov.hk/en/schools/111.html"));
assert.equal(naisProfile.verifiedOn, "2026-10-12");
assert.deepEqual(naisProfile.routes, ["ib", "a-level"], "NAIS profile should preserve both documented Sixth Form exits");
assert.match(naisProfile.snapshot.find(({ field }) => field === "学校身份、校区与筛选资料").value, /授课语言栏标注为Primary Medium of Instruction/u);
assert.match(naisProfile.pending[2], /按年级及校区区分的学费/u);
const naisIbResults = naisProfile.snapshot.find(({ field }) => field === "2026届IBDP校方成绩与数据限制");
assert.ok(naisIbResults);
assert.match(naisIbResults.value, /平均35\.5\/45/u);
assert.match(naisIbResults.value, /25%学生取得40分或以上/u);
assert.match(naisIbResults.value, /未披露完整考生人数/u);
assert.equal(naisIbResults.sourceUrl, "https://www.nordangliaeducation.com/nais-hong-kong/news/2026/7/7/outstanding-ib-diploma-results-for-the-class-of-2026");
const naisIgcseResults = naisProfile.snapshot.find(({ field }) => field === "2026届IGCSE成绩与学生分母");
assert.ok(naisIgcseResults);
assert.match(naisIgcseResults.value, /106名学生、875项科目成绩/u);
assert.match(naisIgcseResults.value, /88.7%取得至少5科/u);
assert.match(naisIgcseResults.value, /不可混用/u);
assert.equal(naisIgcseResults.sourceUrl, "https://www.nordangliaeducation.com/nais-hong-kong/news/2026/8/21/2026-nais-hk-igcse-results");
const naisSixthForm = naisProfile.snapshot.find(({ field }) => field === "2026/27 Sixth Form中心实际启用与课程节点");
assert.ok(naisSixthForm);
assert.match(naisSixthForm.value, /已在Hung Hom Sixth Form Centre开学/u);
assert.match(naisSixthForm.value, /仍须按个人成绩及当届课程安排确认/u);
assert.equal(naisSixthForm.sourceUrl, "https://www.nordangliaeducation.com/nais-hong-kong/news/2026/8/24/sixth-form-centre-weekly-update-24-aug-2026");
const naisSixthFormOpenDay = naisProfile.snapshot.find(({ field }) => field === "Hung Hom Sixth Form Centre开放日（2026-11-11）");
assert.ok(naisSixthFormOpenDay);
assert.equal(naisSixthFormOpenDay.sourceUrl, "https://www.nordangliaeducation.com/nais-hong-kong/open-days");
assert.match(naisSixthFormOpenDay.value, /2026年11月11日16:00–18:00/u);
assert.match(naisSixthFormOpenDay.value, /没有公开可预约时段余量、名额或报名确认状态/u);
assert.match(naisSixthFormOpenDay.value, /不是入学评估、正式申请或学位保证/u);
assert.match(naisProfile.pending.at(-1), /Hung Hom Sixth Form开放日的实际登记时段、名额和确认方式/u);
const naisAdmissions = naisProfile.snapshot.find(({ field }) => field === "2027/28低年级入学评估及中高年级滚动申请（截至2026-10-12）");
assert.ok(naisAdmissions);
