assert.equal(cdnisWithLanguageFilter.matches.length, 0, "unknown CDNIS secondary teaching-medium evidence must not match by inference from primary-school bilingual data");
assert.equal(cdnisWithLanguageFilter.unclassifiedCount, 1, "CDNIS should be shown as unclassified rather than falsely excluded for an unknown secondary medium");
