const fisCandidate = catalogRecords.find(({ school }) => school.profileId === "french-international-school-hong-kong");
assert.ok(fisCandidate, "FIS should remain a curated international candidate with its stream boundary documented");
assert.deepEqual(fisCandidate.routes, ["ib"], "FIS should expose only the verified International Stream IB route");
assert.equal(fisCandidate.school.district, "湾仔区", "the FIS secondary candidate should use the Blue Pool Road campus district");
assert.equal(fisCandidate.school.gender, "Co-ed");
assert.equal(fisCandidate.school.schoolType, "international");
assert.deepEqual(fisCandidate.school.teachingMedium, { chinese: false, english: true }, "FIS English-medium tag is scoped to the International Stream");
assert.equal(filterSecondarySchools([fisCandidate], criteria({ route: "ib", district: "湾仔区", studentGender: "girl", schoolType: "international", language: "english" })).matches.length, 1, "FIS should match IB only when its verified campus/stream facets fit");
assert.equal(filterSecondarySchools([fisCandidate], criteria({ route: "dse" })).matches.length, 0, "FIS must not receive an unsupported DSE tag");
assert.equal(filterSecondarySchools([fisCandidate], criteria({ route: "a-level" })).matches.length, 0, "FIS must not receive an unsupported A-Level tag");
assert.equal(fisCandidate.school.routeEvidence.some((item) => item.sources.some(({ sourceUrl }) => sourceUrl === "https://www.fis.edu.hk/french-stream")), false, "a French Stream boundary source must not be treated as positive IB route evidence");
assert.ok(fisCandidate.school.routeEvidence.find(({ route }) => route === "ib")?.sources.some(({ sourceUrl }) => sourceUrl === "https://www.fis.edu.hk/ibdp"));
