assert.ok(olrProfile.snapshot.some(({ field, value }) => field === "公开考试路线与高中选修（CHSC 2025/26）" && value.includes("DSE") && value.includes("3X选修结构") && value.includes("不保证每年全部开班")));
assert.ok(olrProfile.snapshot.some(({ field, value }) => field === "授课语言与双语能力" && value.includes("除中文相关科目外，其余科目以英语授课") && value.includes("不把“英文授课”误解成全校每一科均以英语教授")));
assert.ok(olrProfile.snapshot.some(({ field, value }) => field === "初中课程特色（CHSC 2025/26）" && value.includes("戏剧（中一）") && value.includes("英语文学（中二、中三）")));
assert.ok(olrProfile.snapshot.some(({ field, value }) => field === "学习方法与全方位学习" && value.includes("三年渐进式思维与学习技巧训练")));
assert.ok(olrProfile.snapshot.some(({ field, value }) => field === "课堂支援与拔尖安排（CHSC 2025/26）" && value.includes("中文、英文、数学按能力小班教学") && value.includes("高中校本增润班")));
assert.ok(olrProfile.snapshot.some(({ field, value }) => field === "学生照顾与班主任安排（CHSC 2025/26）" && value.includes("中一至中四实行双班主任政策")));
assert.ok(olrProfile.snapshot.some(({ field, value }) => field === "SEN及融合教育支援（CHSC 2025/26）" && value.includes("个别学习计划") && value.includes("特别考试安排") && value.includes("按学生情况确认")));
assert.ok(olrProfile.snapshot.some(({ field, value }) => field === "非华语学生中文支援（CHSC 2025/26）" && value.includes("课后中文支援") && value.includes("抽离或分组学习") && value.includes("没有列出服务时数")));
assert.ok(olrProfile.snapshot.some(({ field, value }) => field === "校园设施与交通（CHSC 2025/26）" && value.includes("STEAM创新空间") && value.includes("港铁站步行约10分钟") && value.includes("203C")));
